import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The signed-in user's locale on a sheet. The signed-in user's name travels in the {@code X-User} header.
 * Choosing it is not a change to the sheet: it goes through on an archived sheet, as of a date and for a
 * viewer (see the guards' exclusions). */
@RestController
@RequestMapping("/api/sheets/{sheetId}/locale")
@Validated
public class LocaleController {

    /** A user's locale. */
    public record LocaleView(String locale) {
    }

    /** A locale asked. */
    public record LocaleRequest(@NotNull @Size(max = 10) String locale) {
    }

    private final LocaleService service;

    public LocaleController(LocaleService service) {
        this.service = service;
    }

    @GetMapping
    public LocaleView get(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return new LocaleView(service.localeOf(sheetId.trim(), user.trim()));
    }

    @PutMapping
    public LocaleView choose(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid LocaleRequest request) {
        return new LocaleView(service.choose(sheetId.trim(), user.trim(), request.locale().trim()));
    }
}
package net.officefloor.hq.app.locale;

import java.util.Set;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The locale each user has chosen on a sheet: how the screen shows figures to them. Writes no audit. */
@Service
public class LocaleService {

    /** The locale a user has until they choose another. */
    public static final String DEFAULT = "en";

    /** The locales a user may choose. */
    public static final Set<String> LOCALES = Set.of("en", "de");

    private final SheetRepository sheets;
    private final UserLocaleRepository locales;

    public LocaleService(SheetRepository sheets, UserLocaleRepository locales) {
        this.sheets = sheets;
        this.locales = locales;
    }

    @Transactional(readOnly = true)
    public String localeOf(String sheetId, String user) {
        return locales.findBySheetIdAndUser(sheetId, user).map(UserLocale::getLocale).orElse(DEFAULT);
    }

    @Transactional
    public String choose(String sheetId, String user, String locale) {
        if (!LOCALES.contains(locale)) throw new LocaleUnknownException();
        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
        locales.findBySheetIdAndUser(sheetId, user).ifPresentOrElse(l -> l.setLocale(locale),
                () -> locales.save(new UserLocale(sheetId, user, locale)));
        return locale;
    }
}
